import sys
from collections import defaultdict, deque

# Read input
n, m = map(int, sys.stdin.readline().split())
d = list(map(int, sys.stdin.readline().split()))
edges = [list(map(int, sys.stdin.readline().split())) for _ in range(m)]

# Create adjacency list
adj = defaultdict(list)
for i, (u, v) in enumerate(edges):
    adj[u].append((v, i + 1))
    adj[v].append((u, i + 1))

# Check if a good subset exists
def check_good_subset(n, m, d, adj):
    # Initialize degrees and visited
    degree = [0] * (n + 1)
    visited = [False] * (n + 1)
    queue = deque()

    # Start BFS from any node
    queue.append(1)
    visited[1] = True

    # BFS to calculate degrees and check conditions
    while queue:
        node = queue.popleft()
        expected_degree = d[node - 1]
        actual_degree = degree[node]

        if expected_degree == -1:
            pass
        elif expected_degree == 0:
            if actual_degree % 2 != 0:
                return False
        elif expected_degree == 1:
            if actual_degree % 2 == 0:
                return False

        for neighbor, edge_index in adj[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)
                degree[neighbor] = (degree[node] + 1) % 2

    # Check if all vertices satisfy the degree condition
    for node in range(1, n + 1):
        if d[node - 1] == -1:
            continue
        if d[node - 1] == 0 and degree[node] % 2 != 0:
            return False
        if d[node - 1] == 1 and degree[node] % 2 == 0:
            return False

    return True

# Find the good subset of edges
def find_good_subset(n, m, d, adj):
    if not check_good_subset(n, m, d, adj):
        return -1

    # Use DFS to find the good subset
    good_edges = []
    visited = [False] * (n + 1)

    def dfs(node):
        visited[node] = True
        for neighbor, edge_index in adj[node]:
            if not visited[neighbor]:
                if (degree[node] + degree[neighbor]) % 2 == 1:
                    good_edges.append(edge_index)
                dfs(neighbor)

    # Start DFS from any node
    dfs(1)
    return good_edges

# Calculate degrees and check for good subset
degree = [0] * (n + 1)
good_edges = find_good_subset(n, m, d, adj)

# Output the result
if good_edges == -1:
    print(-1)
else:
    print(len(good_edges))
    for edge_index in good_edges:
        print(edge_index)
